import{_ as n,l,o as e,c as r,v as t,p as s,x as i,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"季节性与日历异象","description":"","frontmatter":{"title":"季节性与日历异象","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/seasonality-anomalies.md","filePath":"quant/seasonality-anomalies.md","lastUpdated":1789023840000}'),p={name:"quant/seasonality-anomalies.md"};function m(c,a,u,A,_,B){const o=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="季节性与日历异象" tabindex="-1">季节性与日历异象 <a class="header-anchor" href="#季节性与日历异象" aria-label="Permalink to &quot;季节性与日历异象&quot;">​</a></h1><div class="epigraph"><p>日历把交易日切成假日、月初、年末窗口；其中一些均值差异在统计上反复出现，经济上却往往是样本、微观结构与税收窗口，而不是可无限加杠杆的第三因子。</p><footer>—— Lakonishok and Smidt, Are Seasonal Anomalies Real? A Ninety-Year Perspective, Review of Financial Studies, 1988</footer></div><p><a href="/quant/factor-timing-feasibility">上一课</a>的择时用估值与宏观状态。季节性的缺口是<strong>用日历当信号</strong>：一月、月末、假期、Sell in May。主干 <a href="/quant/calendar-overnight">日历效应与隔夜</a> 已写周末、隔夜与制度时钟。本课只放策略地图：哪些日历效应还像可交易边缘，哪些已被费用与拥挤吃掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lakonishok–Smidt 用很长样本问：一月效应、周末效应是否经得起子样本。许多「日历 alpha」在发现后衰减，或只存在于小盘、低价、不可交易的一端。问题是识别：效应来自风险（假日窗口的信息到达）、来自微观结构（收盘拍卖、窗口粉饰）、还是来自税收与基金考核日。Heston–Sadka 的截面季节性（同月动量）与指数层面的 Sell in May（Bouman–Jacobsen）不是同一个对象，不能收成一个「日历因子」去和 HML 做马赛克。</p><p>与因子择时：日历信号的广度同样接近 1（对给定市场每年就那几次）。IR 必须按事件数而不是按交易日数来算。</p><h3 id="隔夜不是季节性" tabindex="-1">隔夜不是季节性 <a class="header-anchor" href="#隔夜不是季节性" aria-label="Permalink to &quot;隔夜不是季节性&quot;">​</a></h3><p>隔夜溢价是交易时段切分，见日历课。把它加进「月初效应」会重复计数。策略若声称吃季节性，应排除隔夜与开盘拍卖的冲击模型，否则赚的是微观结构，应归入执行课。</p><p><span class="marginnote">窗口粉饰与税收损失卖出能制造年末到年初的截面，但可预测部分往往被借券与冲击抵消。回测用收盘价在 12 月 31 日调仓，通常不可执行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单：周末/假日、月初月末、财年与税收窗、商品与天气季节（那是曲线，不是股票日历）。检验：子样本、发表前后、市值分层、成本后。事件研究式标准误，见 <a href="/quant/event-study">事件研究</a>。若只在小盘一端显著，容量按小盘算，不要按指数期货名义算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>制度时钟集中了再平衡、考核与信息发布，需求在特定日子倾斜。若倾斜可被灵活资本无成本抵消，效应消失；若必须在收盘拍卖完成（指数、基金），价格压力可重复，那是后课被动流的亲戚，不是神秘月度魔法。</p>',13)),(e(),s(h,null,{default:i(()=>[E(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Cal%5B%22%E6%97%A5%E5%8E%86%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20Risk%5B%22%E9%A3%8E%E9%99%A9%E4%B8%8E%E4%BF%A1%E6%81%AF%E5%88%B0%E8%BE%BE%22%5D%0A%20%20Cal%20--%3E%20Micro%5B%22%E6%8B%8D%E5%8D%96%20%E7%B2%89%E9%A5%B0%20%E7%A8%8E%E6%94%B6%22%5D%0A%20%20Micro%20--%3E%20Press%5B%22%E5%8F%AF%E9%87%8D%E5%A4%8D%E7%9A%84%E4%BB%B7%E6%A0%BC%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20Risk%20--%3E%20Weak%5B%22%E5%8F%91%E8%A1%A8%E5%90%8E%E5%B8%B8%E8%A1%B0%E5%87%8F%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把占星或农历叙事当因子。加密与 24 小时市场的「日历」要重写，不能抄美股周末效应。后课财报期是公司事件簇，不是同一张月度虚拟变量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>季节性要按事件数检验，发表后多数衰减。</li><li>制度窗口的价格压力与「一月魔法」分开。</li><li>隔夜、拍卖不要算进季节性 alpha。</li><li>出处：Lakonishok and Smidt, <em>RFS</em>, 1988；Bouman and Jacobsen, <em>AER</em>, 2002；截面季节见 Heston and Sadka。</li></ul>',4))])}const q=n(p,[["render",m]]);export{k as __pageData,q as default};
